// Fails when the Kubernetes manifests break a rule the cluster depends on
// (K8S-16, K8S-17, K8S-23, K8S-33; structural backing for K8S-09, K8S-18,
// K8S-24, K8S-31 and K8S-04).
//
// Default mode renders k8s/ with `kubectl kustomize --load-restrictor
// LoadRestrictionsNone` (a local render through scripts/kube.mjs; it reads no
// cluster) and requires of every rendered object:
//
//   secrets       no Secret carries `data` or `stringData`: every Secret is
//                 generated by the up command, never versioned;
//   credentials   no container (init or regular) sets a literal `value` for
//                 an env variable whose name contains PASSWORD, SECRET,
//                 ACCESS_KEY or TOKEN;
//   probes        the Deployments api, catalog, notification and worker, when
//                 rendered, probe readiness with GET /health and liveness
//                 with GET /health/live on the service's port (3000, 3001,
//                 3003, 3002);
//   images        those four run ghcr.io/tech-challenge-workshop/<repo>;
//   worker        the worker's CPU request equals its CPU limit equals its
//                 FFMPEG_THREADS (AD-006), and it sets no spec.replicas (the
//                 KEDA HPA owns the count);
//   scaling       a ScaledObject `worker`, when rendered, targets the worker
//                 with min 1 and max 5 replicas and one rabbitmq trigger per
//                 queue - `processing` value "2", `video-validation` value
//                 "20" - each QueueLength over protocol http, authenticated
//                 through an authenticationRef and carrying no host;
//   workloads     the render holds every workload of the topology - the
//                 Deployments api, catalog, notification, worker, rabbitmq,
//                 identity, mailpit, prometheus and grafana, the StatefulSets
//                 postgres and storage, Job storage-init - and the Worker's
//                 ScaledObject `worker` and TriggerAuthentication
//                 `rabbitmq-management` (K8S-02). A manifest dropped from
//                 `resources` fails the check. PENDING names the ones whose
//                 manifest has not landed yet.
//
// It also scans scripts/*.mjs: no script other than scripts/kube.mjs may
// spawn kubectl directly (a bare "kubectl" string, or a string that starts a
// kubectl command line without `--context kind-fiapx`).
//
// The per-object rules pass an empty render; the workloads rule does not, so
// default mode fails on a render that lost a manifest. K8S_RENDER, when set,
// names a file that stands in for the render, so the self-test can spawn this
// script with a forced failure.
//
// The render is read with the strict parser below: the repository has no
// package.json. It understands what kustomize prints - documents separated by
// `---`, block maps and sequences, plain, quoted and multi-line scalars,
// literal and folded block scalars, empty and flat flow collections - and
// throws on anything else (anchors, aliases, tags, nested flow), so a
// construct it does not know fails the check rather than being misread.
//
// `--self-test` needs no cluster: it corrupts an in-memory render once per
// rule and requires the exact message, plants raw kubectl spawns in scanned
// sources, and spawns this script on a corrupted render, which must exit
// non-zero.
import { spawnSync } from 'node:child_process';
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { kubectl } from './kube.mjs';

const SELF = fileURLToPath(import.meta.url);
const REPO_ROOT = join(dirname(SELF), '..');

const REGISTRY = 'ghcr.io/tech-challenge-workshop/';
// The four services: their Deployment name, port (S8 health contract) and
// GHCR repository.
const SERVICES = {
  api: { port: 3000, repo: 'fiap-x-api' },
  catalog: { port: 3001, repo: 'processing-catalog' },
  worker: { port: 3002, repo: 'processing-worker' },
  notification: { port: 3003, repo: 'notification-service' },
};
const CREDENTIAL_ENV = /PASSWORD|SECRET|ACCESS_KEY|TOKEN/i;
const SCALING = { min: 1, max: 5, targets: { processing: '2', 'video-validation': '20' } };
const HELPER = 'kube.mjs';
// Every object the topology needs, as Kind/name (K8S-02).
const REQUIRED = [
  'Deployment/api',
  'Deployment/catalog',
  'Deployment/notification',
  'Deployment/worker',
  'Deployment/rabbitmq',
  'Deployment/identity',
  'Deployment/mailpit',
  'Deployment/prometheus',
  'Deployment/grafana',
  'StatefulSet/postgres',
  'StatefulSet/storage',
  'Job/storage-init',
  'ScaledObject/worker',
  'TriggerAuthentication/rabbitmq-management',
];
// Required objects whose manifest has not landed yet. The task that adds
// each manifest removes it here: grafana (T23).
const PENDING = ['Deployment/grafana'];

// ---------------------------------------------------------------- YAML

function stripComment(line) {
  let quote;
  for (let i = 0; i < line.length; i += 1) {
    const c = line[i];
    if (quote === '"' && c === '\\') {
      i += 1;
    } else if (quote) {
      if (c === quote) quote = undefined;
    } else if (c === '"' || c === "'") {
      quote = c;
    } else if (c === '#' && (i === 0 || /\s/.test(line[i - 1]))) {
      return line.slice(0, i);
    }
  }
  return line;
}

const ESCAPES = { 0: '\0', a: '\x07', b: '\b', t: '\t', '\t': '\t', n: '\n', v: '\v', f: '\f', r: '\r', e: '\x1b', ' ': ' ', '"': '"', '/': '/', '\\': '\\', N: '\x85', _: '\xa0', L: '\u2028', P: '\u2029' };

// Joins the lines of a multi-line flow scalar: a single break folds to a
// space, each empty line becomes a newline.
function foldFlow(lines) {
  let out = lines[0];
  let blanks = 0;
  for (const line of lines.slice(1)) {
    if (line === '') {
      blanks += 1;
      continue;
    }
    out += blanks > 0 ? '\n'.repeat(blanks) : ' ';
    out += line;
    blanks = 0;
  }
  return out;
}

function doubleQuoted(text, n) {
  let out = '';
  let k = 1;
  while (k < text.length) {
    const c = text[k];
    if (c === '"') {
      if (stripComment(text.slice(k + 1)).trim() !== '') throw new Error(`line ${n}: text after a quoted scalar`);
      return out;
    }
    if (c === '\\') {
      const e = text[k + 1];
      if (e === '\n') {
        k += 2;
        continue;
      }
      if (e === 'x' || e === 'u' || e === 'U') {
        const size = { x: 2, u: 4, U: 8 }[e];
        const hex = text.slice(k + 2, k + 2 + size);
        if (!/^[0-9a-fA-F]+$/.test(hex) || hex.length !== size) throw new Error(`line ${n}: bad \\${e} escape`);
        out += String.fromCodePoint(parseInt(hex, 16));
        k += 2 + size;
        continue;
      }
      if (!Object.hasOwn(ESCAPES, e)) throw new Error(`line ${n}: unknown escape \\${e}`);
      out += ESCAPES[e];
      k += 2;
      continue;
    }
    if (c === '\n') {
      let breaks = 0;
      while (text[k] === '\n') {
        breaks += 1;
        k += 1;
      }
      out += breaks === 1 ? ' ' : '\n'.repeat(breaks - 1);
      continue;
    }
    out += c;
    k += 1;
  }
  throw new Error(`line ${n}: unterminated string`);
}

function singleQuoted(text, n) {
  let out = '';
  let k = 1;
  while (k < text.length) {
    const c = text[k];
    if (c === "'") {
      if (text[k + 1] === "'") {
        out += "'";
        k += 2;
        continue;
      }
      if (stripComment(text.slice(k + 1)).trim() !== '') throw new Error(`line ${n}: text after a quoted scalar`);
      return out;
    }
    if (c === '\n') {
      let breaks = 0;
      while (text[k] === '\n') {
        breaks += 1;
        k += 1;
      }
      out += breaks === 1 ? ' ' : '\n'.repeat(breaks - 1);
      continue;
    }
    out += c;
    k += 1;
  }
  throw new Error(`line ${n}: unterminated string`);
}

function plain(text, n) {
  if (text === '{}') return {};
  if (text === '[]') return [];
  if (text.startsWith('[') && text.endsWith(']')) {
    const inner = text.slice(1, -1);
    if (/[[\]{}]/.test(inner)) throw new Error(`line ${n}: nested flow collections are not supported`);
    const items = [];
    let current = '';
    let quote;
    for (const c of inner) {
      if (quote) {
        current += c;
        if (c === quote) quote = undefined;
      } else if (c === '"' || c === "'") {
        quote = c;
        current += c;
      } else if (c === ',') {
        items.push(current);
        current = '';
      } else {
        current += c;
      }
    }
    if (current.trim() !== '') items.push(current);
    return items.map((item) => inlineScalar([item.trim()], n));
  }
  if (/^[[\]{}&*!%@`|>?]/.test(text) || /^- /.test(text)) throw new Error(`line ${n}: unsupported YAML value "${text}"`);
  if (text === 'true') return true;
  if (text === 'false') return false;
  if (text === 'null' || text === '~') return null;
  if (/^[-+]?\d+$/.test(text) || /^[-+]?(\d+\.\d*|\.\d+)([eE][-+]?\d+)?$/.test(text)) return Number(text);
  return text;
}

// A flow scalar given as its trimmed lines ('' for an empty line).
function inlineScalar(lines, n) {
  const first = lines[0];
  if (first.startsWith('"')) return doubleQuoted(lines.join('\n'), n);
  if (first.startsWith("'")) return singleQuoted(lines.join('\n'), n);
  if (lines.length === 1) return plain(first, n);
  if (/^[[\]{}&*!%@`|>?]/.test(first)) throw new Error(`line ${n}: unsupported YAML value "${first}"`);
  return foldFlow(lines);
}

function foldBlock(lines) {
  const moreIndented = (s) => /^[ \t]/.test(s);
  let out = '';
  lines.forEach((line, k) => {
    if (k === 0) {
      out = line;
    } else if (line === '') {
      out += '\n';
    } else if (moreIndented(line) || moreIndented(lines[k - 1])) {
      out += `\n${line}`;
    } else if (lines[k - 1] === '') {
      out += line;
    } else {
      out += ` ${line}`;
    }
  });
  return out;
}

const KEY = /^("(?:[^"\\]|\\.)*"|'(?:[^']|'')*'|[^\s"'#[\]{},&*!|>%@`?-][^:]*?|-[^\s:][^:]*?)\s*:(?:\s+(.*)|$)/;

function parseDocument(rows) {
  let i = 0;
  const info = (k) => {
    const { n, raw } = rows[k];
    const indent = /^ */.exec(raw)[0].length;
    const text = stripComment(raw).trim();
    if (text !== '' && raw[indent] === '\t') throw new Error(`line ${n}: tab indentation`);
    return { n, raw, indent, text };
  };
  const next = () => {
    while (i < rows.length && info(i).text === '') i += 1;
    return i < rows.length ? info(i) : undefined;
  };
  const isItem = (line) => line.text === '-' || line.text.startsWith('- ');

  // The continuation lines of a flow scalar that began on row i - 1: every
  // following line indented deeper than `parent`, empty lines included when
  // more follow. Plain scalars end at a comment line.
  function continuation(parent, isPlain) {
    const parts = [];
    const pending = [];
    let j = i;
    while (j < rows.length) {
      const raw = rows[j].raw;
      if (raw.trim() === '') {
        pending.push('');
        j += 1;
        continue;
      }
      const lead = /^ */.exec(raw)[0].length;
      if (lead <= parent) break;
      const text = isPlain ? stripComment(raw).trim() : raw.trim();
      if (isPlain && text === '') break;
      parts.push(...pending, text);
      pending.length = 0;
      j += 1;
    }
    i = j - pending.length;
    return parts;
  }

  function blockScalar(header, parent, n) {
    const match = /^([|>])(?:([1-9])([+-]?)|([+-]?)([1-9]?))\s*$/.exec(stripComment(header).trim());
    if (!match) throw new Error(`line ${n}: bad block scalar header "${header}"`);
    const style = match[1];
    const indicator = Number(match[2] ?? match[5]) || 0;
    const chomp = match[3] || match[4] || '';
    let contentIndent = indicator > 0 ? parent + indicator : undefined;
    const lines = [];
    let j = i;
    while (j < rows.length) {
      const raw = rows[j].raw;
      if (raw.trim() === '') {
        lines.push(contentIndent === undefined ? '' : raw.slice(contentIndent));
        j += 1;
        continue;
      }
      const lead = /^ */.exec(raw)[0].length;
      if (contentIndent === undefined) {
        if (lead <= parent) break;
        contentIndent = lead;
      }
      if (lead < contentIndent) break;
      lines.push(raw.slice(contentIndent));
      j += 1;
    }
    let trailing = 0;
    while (lines.length > 0 && lines.at(-1).trim() === '') {
      lines.pop();
      trailing += 1;
    }
    i = j - trailing;
    const body = style === '|' ? lines.join('\n') : foldBlock(lines);
    if (lines.length === 0) return chomp === '+' ? '\n'.repeat(trailing) : '';
    if (chomp === '-') return body;
    if (chomp === '+') return `${body}\n${'\n'.repeat(trailing)}`;
    return `${body}\n`;
  }

  function value(rest, parent, n, inMap) {
    if (rest === '') {
      const nx = next();
      if (nx && nx.indent > parent) return node(nx.indent);
      if (inMap && nx && nx.indent === parent && isItem(nx)) return sequence(parent);
      return null;
    }
    if (/^[|>]/.test(rest)) return blockScalar(rest, parent, n);
    const isPlain = !/^["']/.test(rest);
    return inlineScalar([rest, ...continuation(parent, isPlain)], n);
  }

  function map(indent) {
    const out = {};
    for (;;) {
      const line = next();
      if (!line || line.indent < indent || isItem(line)) break;
      if (line.indent > indent) throw new Error(`line ${line.n}: unexpected indentation`);
      const match = KEY.exec(line.text);
      if (!match) throw new Error(`line ${line.n}: expected "key: value", got "${line.text}"`);
      const key = String(inlineScalar([match[1]], line.n));
      if (Object.hasOwn(out, key)) throw new Error(`line ${line.n}: duplicate key "${key}"`);
      // The value as written, so a quoted value keeps its own `#`.
      const rest = match[2] === undefined ? '' : line.raw.slice(line.raw.indexOf(match[2], line.indent + match[1].length)).trim();
      i += 1;
      out[key] = value(/^["']/.test(rest) ? rest : stripComment(rest).trim(), indent, line.n, true);
    }
    return out;
  }

  function sequence(indent) {
    const out = [];
    for (;;) {
      const line = next();
      if (!line || line.indent < indent || !isItem(line)) break;
      if (line.indent > indent) throw new Error(`line ${line.n}: unexpected indentation`);
      const rest = line.text === '-' ? '' : line.text.slice(1).trimStart();
      if (rest === '') {
        i += 1;
        const nx = next();
        out.push(nx && nx.indent > indent ? node(nx.indent) : null);
      } else if (rest === '-' || rest.startsWith('- ')) {
        throw new Error(`line ${line.n}: nested inline sequences are not supported`);
      } else if (KEY.test(rest) && !/^["']/.test(rest.trim()) || /^["'].*["']\s*:(\s|$)/.test(rest)) {
        const childIndent = line.indent + (line.text.length - rest.length);
        rows[i] = { n: line.n, raw: ' '.repeat(childIndent) + line.raw.slice(childIndent) };
        out.push(map(childIndent));
      } else {
        i += 1;
        const raw = line.raw.slice(line.raw.indexOf(rest, line.indent + 1)).trim();
        out.push(value(/^["']/.test(raw) ? raw : stripComment(raw).trim(), indent, line.n, false));
      }
    }
    return out;
  }

  function node(indent) {
    const line = next();
    return isItem(line) ? sequence(indent) : map(indent);
  }

  const first = next();
  if (!first) return null;
  const result = node(first.indent);
  const left = next();
  if (left) throw new Error(`line ${left.n}: unexpected indentation`);
  return result;
}

// Every non-empty document of a `---`-separated stream.
export function parseYamlStream(text) {
  const documents = [[]];
  text.split('\n').forEach((raw, index) => {
    const n = index + 1;
    if (/^---\s*$/.test(raw)) {
      documents.push([]);
    } else if (/^(\.\.\.|%)/.test(raw) || /^--- /.test(raw)) {
      throw new Error(`line ${n}: unsupported document marker "${raw.trim()}"`);
    } else {
      documents.at(-1).push({ n, raw: raw.replace(/\r$/, '') });
    }
  });
  return documents.map(parseDocument).filter((doc) => doc !== null);
}

// ---------------------------------------------------------------- rules

const id = (obj) => `${obj.kind}/${obj.metadata?.name}`;

function podSpec(obj) {
  if (obj.kind === 'Pod') return obj.spec;
  if (obj.kind === 'CronJob') return obj.spec?.jobTemplate?.spec?.template?.spec;
  return obj.spec?.template?.spec;
}

const list = (value) => (Array.isArray(value) ? value : []);

// CPU quantity in cores: "1", 1, "1.5", "500m"; NaN otherwise.
function cores(quantity) {
  const m = /^(\d+(?:\.\d+)?)(m?)$/.exec(String(quantity ?? ''));
  if (!m) return NaN;
  return m[2] === 'm' ? Number(m[1]) / 1000 : Number(m[1]);
}

function probePort(port, container) {
  if (typeof port === 'number') return port;
  return list(container.ports).find((p) => p.name === port)?.containerPort;
}

function probeMatches(probe, path, port, container) {
  const get = probe?.httpGet;
  return get?.path === path && probePort(get.port, container) === port;
}

export function manifestProblems(objects) {
  const problems = [];
  objects.forEach((obj, index) => {
    if (obj === null || typeof obj !== 'object' || Array.isArray(obj) || typeof obj.kind !== 'string') {
      problems.push(`rendered document ${index + 1} is not a Kubernetes object`);
      return;
    }
    const where = id(obj);

    if (obj.kind === 'Secret' && (Object.hasOwn(obj, 'data') || Object.hasOwn(obj, 'stringData'))) {
      problems.push(`${where}: a versioned Secret must not carry data or stringData; the up command generates every Secret`);
    }

    const spec = podSpec(obj);
    const containers = [...list(spec?.initContainers), ...list(spec?.containers)];
    for (const container of containers) {
      for (const env of list(container.env)) {
        if (CREDENTIAL_ENV.test(String(env?.name)) && Object.hasOwn(env, 'value')) {
          problems.push(`${where}: container ${container.name} sets ${env.name} as a literal value; credentials come from a Secret (secretKeyRef)`);
        }
      }
    }

    const service = obj.kind === 'Deployment' ? SERVICES[obj.metadata?.name] : undefined;
    if (service) {
      const main = list(spec?.containers).find((c) => c.name === obj.metadata.name) ?? list(spec?.containers)[0] ?? {};
      if (!probeMatches(main.readinessProbe, '/health', service.port, main)) {
        problems.push(`${where}: the readiness probe must be GET /health on port ${service.port}`);
      }
      if (!probeMatches(main.livenessProbe, '/health/live', service.port, main)) {
        problems.push(`${where}: the liveness probe must be GET /health/live on port ${service.port}`);
      }
      const image = String(main.image ?? '');
      if (!new RegExp(`^${(REGISTRY + service.repo).replaceAll('.', '\\.')}[:@]`).test(image)) {
        problems.push(`${where}: the image must be ${REGISTRY}${service.repo}, got "${image}"`);
      }
    }

    if (obj.kind === 'Deployment' && obj.metadata?.name === 'worker') {
      if (Object.hasOwn(obj.spec ?? {}, 'replicas')) {
        problems.push(`${where}: must not set spec.replicas; the KEDA HPA owns the replica count`);
      }
      const main = list(spec?.containers).find((c) => c.name === 'worker') ?? list(spec?.containers)[0] ?? {};
      const request = main.resources?.requests?.cpu;
      const limit = main.resources?.limits?.cpu;
      const threadsEnv = list(main.env).find((e) => e?.name === 'FFMPEG_THREADS');
      const threads = threadsEnv?.value;
      if (!/^[1-9]\d*$/.test(String(threads ?? ''))) {
        problems.push(`${where}: FFMPEG_THREADS must be a positive integer literal, got ${JSON.stringify(threads ?? null)}`);
      } else if (!(cores(request) === cores(limit))) {
        problems.push(`${where}: the CPU request (${JSON.stringify(request ?? null)}) must equal the CPU limit (${JSON.stringify(limit ?? null)})`);
      } else if (cores(limit) !== Number(threads)) {
        problems.push(`${where}: the CPU limit is ${JSON.stringify(limit)} but FFMPEG_THREADS is ${JSON.stringify(threads)}; they must be equal (AD-006)`);
      }
    }

    if (obj.kind === 'ScaledObject' && obj.metadata?.name === 'worker') {
      const s = obj.spec ?? {};
      if (s.scaleTargetRef?.name !== 'worker') problems.push(`${where}: must scale the worker Deployment (scaleTargetRef.name worker)`);
      if (s.minReplicaCount !== SCALING.min) problems.push(`${where}: minReplicaCount must be ${SCALING.min}, got ${JSON.stringify(s.minReplicaCount ?? null)}`);
      if (s.maxReplicaCount !== SCALING.max) problems.push(`${where}: maxReplicaCount must be ${SCALING.max}, got ${JSON.stringify(s.maxReplicaCount ?? null)}`);
      for (const [queue, target] of Object.entries(SCALING.targets)) {
        const trigger = list(s.triggers).find((t) => t?.type === 'rabbitmq' && t.metadata?.queueName === queue);
        if (!trigger) {
          problems.push(`${where}: no rabbitmq trigger for queue ${queue}`);
          continue;
        }
        const m = trigger.metadata;
        if (String(m.value) !== target) problems.push(`${where}: queue ${queue} must target "${target}" messages per replica, got ${JSON.stringify(m.value ?? null)}`);
        if (m.mode !== 'QueueLength') problems.push(`${where}: queue ${queue} must use mode QueueLength, got ${JSON.stringify(m.mode ?? null)}`);
        if (m.protocol !== 'http') problems.push(`${where}: queue ${queue} must use protocol http (the management API counts unacknowledged messages), got ${JSON.stringify(m.protocol ?? null)}`);
        if (!trigger.authenticationRef?.name) problems.push(`${where}: queue ${queue} must authenticate through a TriggerAuthentication (authenticationRef)`);
        if (Object.hasOwn(m, 'host') || Object.hasOwn(m, 'hostFromEnv')) {
          problems.push(`${where}: queue ${queue} must not carry a host; the connection string comes from the TriggerAuthentication's Secret`);
        }
      }
    }
  });
  return problems;
}

// The required objects (REQUIRED less PENDING) the render lacks.
export function missingWorkloads(objects) {
  const present = new Set(objects.filter((o) => o !== null && typeof o === 'object').map(id));
  return REQUIRED.filter((name) => !PENDING.includes(name) && !present.has(name))
    .map((name) => `${name}: required by the topology but missing from the render; add its manifest to k8s/kustomization.yaml resources`);
}

// `files` maps a script's file name to its source. Only kube.mjs may spawn
// kubectl; elsewhere a bare "kubectl" string (a command to spawn) or a string
// that starts a kubectl command line without the pinned context is refused.
// Lines that are `//` comments are not scanned.
export function rawKubectlProblems(files) {
  const problems = [];
  const bare = /(['"`])(?:[^'"`\s]*\/)?kubectl\1/;
  const commandLine = /(['"`])(?:[^'"`\s]*\/)?kubectl\s+(?!--context kind-fiapx\b)/;
  for (const [name, source] of Object.entries(files)) {
    if (name === HELPER) continue;
    const lines = source.split('\n');
    // A `//` comment line documents a command; it spawns nothing.
    const at = lines.findIndex((line) => !/^\s*\/\//.test(line) && (bare.test(line) || commandLine.test(line)));
    if (at !== -1) {
      problems.push(`scripts/${name}:${at + 1}: spawns kubectl directly; call kubectl() from scripts/kube.mjs, which pins --context kind-fiapx`);
    }
  }
  return problems;
}

// ---------------------------------------------------------------- main

function fail(message) {
  console.error(`check-kubernetes: ${message}`);
  process.exit(1);
}

function render() {
  if (process.env.K8S_RENDER !== undefined) return readFileSync(process.env.K8S_RENDER, 'utf8');
  const dir = join(REPO_ROOT, 'k8s');
  if (!existsSync(join(dir, 'kustomization.yaml'))) return '';
  const run = kubectl(['kustomize', '--load-restrictor', 'LoadRestrictionsNone', dir]);
  if (run.error) fail(`could not run the kustomize render: ${run.error.message}`);
  if (run.status !== 0) fail(`the kustomize render of k8s/ failed:\n${run.stderr.trim()}`);
  return run.stdout;
}

function scriptSources(dir) {
  return Object.fromEntries(
    readdirSync(dir)
      .filter((f) => f.endsWith('.mjs') && !f.startsWith('._'))
      .map((f) => [f, readFileSync(join(dir, f), 'utf8')]),
  );
}

// `complete` adds the workloads rule, which default mode always applies; the
// per-object self-test cases leave it off, since their renders are partial.
function problemsOf(text, files, complete = false) {
  let objects;
  try {
    objects = parseYamlStream(text);
  } catch (error) {
    return { count: 0, problems: [`the render cannot be read: ${error.message}`, ...rawKubectlProblems(files)] };
  }
  const missing = complete ? missingWorkloads(objects) : [];
  return { count: objects.length, problems: [...manifestProblems(objects), ...missing, ...rawKubectlProblems(files)] };
}

function main() {
  const { count, problems } = problemsOf(render(), scriptSources(join(REPO_ROOT, 'scripts')), true);
  if (problems.length > 0) {
    for (const problem of problems) console.error(`check-kubernetes: ${problem}`);
    process.exit(1);
  }
  const pending = PENDING.length > 0 ? ` (pending: ${PENDING.join(', ')})` : '';
  console.log(`check-kubernetes: ${count} rendered objects pass the offline rules (secrets, credentials, probes, images, worker sizing and replicas, scaling) and hold every required workload${pending}; only scripts/kube.mjs spawns kubectl`);
}

// ---------------------------------------------------------------- self-test

function serviceDoc(name, port, repo) {
  return `apiVersion: apps/v1
kind: Deployment
metadata:
  labels:
    app: ${name}
  name: ${name}
  namespace: fiapx
spec:
  selector:
    matchLabels:
      app: ${name}
  template:
    metadata:
      labels:
        app: ${name}
    spec:
      containers:
      - env:
        - name: DATABASE_PASSWORD
          valueFrom:
            secretKeyRef:
              key: CATALOG_DB_PASSWORD
              name: fiapx-postgres
        - name: "PORT"
          value: "${port}"
        image: ghcr.io/tech-challenge-workshop/${repo}:main
        imagePullPolicy: Always
        livenessProbe:
          httpGet:
            path: /health/live
            port: ${port}
        name: ${name}
        ports:
        - containerPort: ${port}
          name: http
        readinessProbe:
          httpGet:
            path: /health
            port: http
`;
}

// A render shaped like `kubectl kustomize` prints it.
function goodDocs() {
  return {
    namespace: 'apiVersion: v1\nkind: Namespace\nmetadata:\n  name: fiapx\n',
    config: `apiVersion: v1
data:
  bootstrap.sh: |
    #!/bin/sh
    # not a comment to YAML
    set -eu

    aws s3api head-bucket --bucket "$STORAGE_BUCKET" || aws s3api create-bucket --bucket "$STORAGE_BUCKET"
  enabled_plugins: |-
    [rabbitmq_management,rabbitmq_prometheus].
kind: ConfigMap
metadata:
  annotations:
    note: a long note that kustomize wraps onto a second line when it passes the
      line width
  name: fiapx-storage-bootstrap
  namespace: fiapx
`,
    api: serviceDoc('api', 3000, 'fiap-x-api'),
    catalog: serviceDoc('catalog', 3001, 'processing-catalog'),
    notification: serviceDoc('notification', 3003, 'notification-service'),
    worker: `apiVersion: apps/v1
kind: Deployment
metadata:
  name: worker
  namespace: fiapx
spec:
  selector:
    matchLabels:
      app: worker
  template:
    metadata:
      labels:
        app: worker
    spec:
      containers:
      - env:
        - name: FFMPEG_THREADS
          value: "1"
        - name: STORAGE_ACCESS_KEY
          valueFrom:
            secretKeyRef:
              key: ACCESS_KEY
              name: fiapx-storage
        image: ghcr.io/tech-challenge-workshop/processing-worker:main
        livenessProbe:
          httpGet:
            path: /health/live
            port: 3002
        name: worker
        readinessProbe:
          httpGet:
            path: /health
            port: 3002
        resources:
          limits:
            cpu: "1"
            memory: 1Gi
          requests:
            cpu: "1"
            memory: 512Mi
      initContainers:
      - command:
        - sh
        - -c
        - |-
          until aws s3api head-bucket --bucket fiapx; do sleep 2; done
        env:
        - name: AWS_SECRET_ACCESS_KEY
          valueFrom:
            secretKeyRef:
              key: SECRET_KEY
              name: fiapx-storage
        image: amazon/aws-cli:2.37.4
        name: wait-for-bucket
      terminationGracePeriodSeconds: 30
`,
    scaledObject: `apiVersion: keda.sh/v1alpha1
kind: ScaledObject
metadata:
  name: worker
  namespace: fiapx
spec:
  advanced:
    horizontalPodAutoscalerConfig:
      behavior:
        scaleDown:
          stabilizationWindowSeconds: 60
  maxReplicaCount: 5
  minReplicaCount: 1
  pollingInterval: 5
  scaleTargetRef:
    name: worker
  triggers:
  - authenticationRef:
      name: rabbitmq-management
    metadata:
      mode: QueueLength
      protocol: http
      queueName: processing
      value: "2"
    type: rabbitmq
  - authenticationRef:
      name: rabbitmq-management
    metadata:
      mode: QueueLength
      protocol: http
      queueName: video-validation
      value: "20"
    type: rabbitmq
`,
    triggerAuth: `apiVersion: keda.sh/v1alpha1
kind: TriggerAuthentication
metadata:
  name: rabbitmq-management
  namespace: fiapx
spec:
  secretTargetRef:
  - key: host
    name: fiapx-keda-rabbitmq
    parameter: host
`,
  };
}

const joinDocs = (docs) => Object.values(docs).join('---\n');

// goodDocs plus a minimal object for every other required workload: a
// render that passes the workloads rule. Keyed by Kind/name.
function completeDocs() {
  const docs = {};
  for (const text of Object.values(goodDocs())) docs[id(parseYamlStream(text)[0])] = text;
  const apiVersions = { Deployment: 'apps/v1', StatefulSet: 'apps/v1', Job: 'batch/v1' };
  for (const name of REQUIRED) {
    if (PENDING.includes(name) || Object.hasOwn(docs, name)) continue;
    const [kind, objectName] = name.split('/');
    docs[name] = `apiVersion: ${apiVersions[kind]}\nkind: ${kind}\nmetadata:\n  name: ${objectName}\n  namespace: fiapx\n`;
  }
  return docs;
}

function selfTest() {
  const failures = [];
  let rejected = 0;
  let accepted = 0;
  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

  // Replaces `from` with `to` in one document; `from` must occur exactly once
  // there, so a fixture drift cannot turn a corruption into a no-op.
  const corrupt = (doc, from, to) => (docs) => {
    const parts = docs[doc].split(from);
    if (parts.length !== 2) throw new Error(`fixture: ${JSON.stringify(from)} occurs ${parts.length - 1} times in ${doc}`);
    docs[doc] = parts.join(to);
  };
  const append = (doc, text) => (docs) => {
    docs[doc] = text;
  };
  const expectRender = (name, mutate, expected) => {
    const docs = goodDocs();
    try {
      mutate(docs);
    } catch (error) {
      failures.push(`${name}: ${error.message}`);
      return;
    }
    const got = problemsOf(joinDocs(docs), {}).problems;
    if (!same(got, expected)) {
      failures.push(`${name}: got ${JSON.stringify(got)}, expected ${JSON.stringify(expected)}`);
    } else if (expected.length > 0) {
      rejected += 1;
    } else {
      accepted += 1;
    }
  };

  // Accepted renders. The good render already holds credential-named env
  // from secretKeyRef and a non-credential literal (PORT).
  expectRender('the good render', () => {}, []);
  expectRender('an empty render', (docs) => { for (const k of Object.keys(docs)) delete docs[k]; }, []);
  expectRender('a render with only the namespace', (docs) => { for (const k of Object.keys(docs)) if (k !== 'namespace') delete docs[k]; }, []);
  expectRender('a Secret with neither data nor stringData', append('secret', 'apiVersion: v1\nkind: Secret\nmetadata:\n  name: fiapx-empty\ntype: Opaque\n'), []);
  expectRender('cpu "1000m" request with limit "1" and 1 thread', corrupt('worker', '          requests:\n            cpu: "1"', '          requests:\n            cpu: 1000m'), []);

  // K8S-17: committed Secret data.
  expectRender('Secret with data', append('secret', 'apiVersion: v1\ndata:\n  PASSWORD: cGFzcw==\nkind: Secret\nmetadata:\n  name: fiapx-postgres\n'),
    ['Secret/fiapx-postgres: a versioned Secret must not carry data or stringData; the up command generates every Secret']);
  expectRender('Secret with stringData', append('secret', 'apiVersion: v1\nkind: Secret\nmetadata:\n  name: fiapx-storage\nstringData:\n  ACCESS_KEY: x\n'),
    ['Secret/fiapx-storage: a versioned Secret must not carry data or stringData; the up command generates every Secret']);
  // K8S-16: literal credential env, in a regular and in an init container.
  expectRender('literal DATABASE_PASSWORD', corrupt('catalog', '          valueFrom:\n            secretKeyRef:\n              key: CATALOG_DB_PASSWORD\n              name: fiapx-postgres\n', '          value: catalog\n'),
    ['Deployment/catalog: container catalog sets DATABASE_PASSWORD as a literal value; credentials come from a Secret (secretKeyRef)']);
  expectRender('literal AWS_SECRET_ACCESS_KEY in an init container', corrupt('worker', '        - name: AWS_SECRET_ACCESS_KEY\n          valueFrom:\n            secretKeyRef:\n              key: SECRET_KEY\n              name: fiapx-storage\n', '        - name: AWS_SECRET_ACCESS_KEY\n          value: ""\n'),
    ['Deployment/worker: container wait-for-bucket sets AWS_SECRET_ACCESS_KEY as a literal value; credentials come from a Secret (secretKeyRef)']);
  expectRender('literal STORAGE_ACCESS_KEY', corrupt('worker', '        - name: STORAGE_ACCESS_KEY\n          valueFrom:\n            secretKeyRef:\n              key: ACCESS_KEY\n              name: fiapx-storage\n', '        - name: STORAGE_ACCESS_KEY\n          value: fiapx-dev\n'),
    ['Deployment/worker: container worker sets STORAGE_ACCESS_KEY as a literal value; credentials come from a Secret (secretKeyRef)']);
  expectRender('literal GHCR_TOKEN in a Job', append('job', 'apiVersion: batch/v1\nkind: Job\nmetadata:\n  name: storage-init\nspec:\n  template:\n    spec:\n      containers:\n      - env:\n        - name: GHCR_TOKEN\n          value: abc\n        image: amazon/aws-cli:2.37.4\n        name: init\n'),
    ['Job/storage-init: container init sets GHCR_TOKEN as a literal value; credentials come from a Secret (secretKeyRef)']);
  // K8S-09: probes.
  expectRender('readiness on /healthz', corrupt('api', '            path: /health\n            port: http', '            path: /healthz\n            port: http'),
    ['Deployment/api: the readiness probe must be GET /health on port 3000']);
  expectRender('readiness on the wrong port', corrupt('notification', '        - containerPort: 3003\n          name: http', '        - containerPort: 3003\n          name: web\n        - containerPort: 3004\n          name: http'),
    ['Deployment/notification: the readiness probe must be GET /health on port 3003']);
  expectRender('liveness on /health', corrupt('catalog', 'path: /health/live', 'path: /health'),
    ['Deployment/catalog: the liveness probe must be GET /health/live on port 3001']);
  expectRender('no liveness probe', corrupt('worker', '        livenessProbe:\n          httpGet:\n            path: /health/live\n            port: 3002\n', ''),
    ['Deployment/worker: the liveness probe must be GET /health/live on port 3002']);
  // K8S-31: images.
  expectRender('a locally built worker image', corrupt('worker', 'image: ghcr.io/tech-challenge-workshop/processing-worker:main', 'image: processing-worker:ci'),
    ['Deployment/worker: the image must be ghcr.io/tech-challenge-workshop/processing-worker, got "processing-worker:ci"']);
  expectRender('a near-miss registry prefix', corrupt('api', 'ghcr.io/tech-challenge-workshop/fiap-x-api:main', 'ghcr.io/tech-challenge-workshop-fork/fiap-x-api:main'),
    ['Deployment/api: the image must be ghcr.io/tech-challenge-workshop/fiap-x-api, got "ghcr.io/tech-challenge-workshop-fork/fiap-x-api:main"']);
  expectRender('another service\'s image', corrupt('catalog', 'processing-catalog:main', 'processing-catalog-v2:main'),
    ['Deployment/catalog: the image must be ghcr.io/tech-challenge-workshop/processing-catalog, got "ghcr.io/tech-challenge-workshop/processing-catalog-v2:main"']);
  // K8S-23 and the no-replicas rule.
  expectRender('worker with replicas', corrupt('worker', 'spec:\n  selector:', 'spec:\n  replicas: 1\n  selector:'),
    ['Deployment/worker: must not set spec.replicas; the KEDA HPA owns the replica count']);
  expectRender('worker CPU request below the limit', corrupt('worker', '          requests:\n            cpu: "1"', '          requests:\n            cpu: 500m'),
    ['Deployment/worker: the CPU request ("500m") must equal the CPU limit ("1")']);
  expectRender('worker threads 2 with CPU 1', corrupt('worker', 'value: "1"', 'value: "2"'),
    ['Deployment/worker: the CPU limit is "1" but FFMPEG_THREADS is "2"; they must be equal (AD-006)']);
  expectRender('worker threads 0', corrupt('worker', 'value: "1"', 'value: "0"'),
    ['Deployment/worker: FFMPEG_THREADS must be a positive integer literal, got "0"']);
  expectRender('worker without a CPU request', corrupt('worker', '          requests:\n            cpu: "1"\n', '          requests:\n'),
    ['Deployment/worker: the CPU request (null) must equal the CPU limit ("1")']);
  // K8S-18 and K8S-24: scaling.
  expectRender('ScaledObject max 10', corrupt('scaledObject', 'maxReplicaCount: 5', 'maxReplicaCount: 10'),
    ['ScaledObject/worker: maxReplicaCount must be 5, got 10']);
  expectRender('ScaledObject min 0', corrupt('scaledObject', 'minReplicaCount: 1', 'minReplicaCount: 0'),
    ['ScaledObject/worker: minReplicaCount must be 1, got 0']);
  expectRender('ScaledObject targets another Deployment', corrupt('scaledObject', '  scaleTargetRef:\n    name: worker', '  scaleTargetRef:\n    name: api'),
    ['ScaledObject/worker: must scale the worker Deployment (scaleTargetRef.name worker)']);
  expectRender('processing target 3', corrupt('scaledObject', 'value: "2"', 'value: "3"'),
    ['ScaledObject/worker: queue processing must target "2" messages per replica, got "3"']);
  expectRender('video-validation target 2 (near miss of 20)', corrupt('scaledObject', 'value: "20"', 'value: "2"'),
    ['ScaledObject/worker: queue video-validation must target "20" messages per replica, got "2"']);
  expectRender('no processing trigger', corrupt('scaledObject', 'queueName: processing', 'queueName: notification.terminal'),
    ['ScaledObject/worker: no rabbitmq trigger for queue processing']);
  expectRender('processing over amqp', corrupt('scaledObject', '      protocol: http\n      queueName: processing', '      protocol: amqp\n      queueName: processing'),
    ['ScaledObject/worker: queue processing must use protocol http (the management API counts unacknowledged messages), got "amqp"']);
  expectRender('video-validation in MessageRate mode', corrupt('scaledObject', '      mode: QueueLength\n      protocol: http\n      queueName: video-validation', '      mode: MessageRate\n      protocol: http\n      queueName: video-validation'),
    ['ScaledObject/worker: queue video-validation must use mode QueueLength, got "MessageRate"']);
  expectRender('video-validation without authenticationRef', corrupt('scaledObject', '  - authenticationRef:\n      name: rabbitmq-management\n    metadata:\n      mode: QueueLength\n      protocol: http\n      queueName: video-validation', '  - metadata:\n      mode: QueueLength\n      protocol: http\n      queueName: video-validation'),
    ['ScaledObject/worker: queue video-validation must authenticate through a TriggerAuthentication (authenticationRef)']);
  expectRender('processing with a host in the trigger', corrupt('scaledObject', '      queueName: processing\n', '      queueName: processing\n      host: http://guest:guest@rabbitmq:15672/\n'),
    ['ScaledObject/worker: queue processing must not carry a host; the connection string comes from the TriggerAuthentication\'s Secret']);
  // An unreadable render fails rather than passing as empty.
  expectRender('an anchor in the render', corrupt('namespace', 'name: fiapx', 'name: &n fiapx'),
    ['the render cannot be read: line 4: unsupported YAML value "&n fiapx"']);

  // K8S-02: every required workload is in the render. Each case starts from
  // the complete render and applies the workloads rule, as default mode does.
  const expectComplete = (name, mutate, expected) => {
    const docs = completeDocs();
    mutate(docs);
    const got = problemsOf(joinDocs(docs), {}, true).problems;
    if (!same(got, expected)) {
      failures.push(`${name}: got ${JSON.stringify(got)}, expected ${JSON.stringify(expected)}`);
    } else if (expected.length > 0) {
      rejected += 1;
    } else {
      accepted += 1;
    }
  };
  const missing = (name) => `${name}: required by the topology but missing from the render; add its manifest to k8s/kustomization.yaml resources`;
  expectComplete('the complete render', () => {}, []);
  // A manifest dropped from `resources` takes its objects out of the render.
  for (const name of REQUIRED.filter((n) => !PENDING.includes(n))) {
    expectComplete(`the render without ${name}`, (docs) => { delete docs[name]; }, [missing(name)]);
  }
  expectComplete('two manifests dropped', (docs) => { delete docs['Deployment/catalog']; delete docs['Job/storage-init']; },
    [missing('Deployment/catalog'), missing('Job/storage-init')]);
  // The kind is part of the requirement: a Deployment postgres is not the StatefulSet.
  expectComplete('postgres as a Deployment', (docs) => { docs['StatefulSet/postgres'] = docs['StatefulSet/postgres'].replace('apiVersion: apps/v1\nkind: StatefulSet', 'apiVersion: apps/v1\nkind: Deployment'); },
    [missing('StatefulSet/postgres')]);
  expectComplete('a ScaledObject named workers', (docs) => { docs['ScaledObject/worker'] = docs['ScaledObject/worker'].replace('  name: worker\n  namespace: fiapx', '  name: workers\n  namespace: fiapx'); },
    [missing('ScaledObject/worker')]);
  // A pending workload is not required until its task lands its manifest.
  for (const name of PENDING) {
    expectComplete(`pending ${name} absent`, (docs) => { delete docs[name]; }, []);
  }

  // The parser reads what the rules depend on exactly.
  const parsed = parseYamlStream(joinDocs(goodDocs()));
  const cm = parsed.find((o) => o.kind === 'ConfigMap');
  const parserCases = [
    ['document count', parsed.length, 8],
    ['literal block scalar keeps # lines and the empty line', cm.data['bootstrap.sh'],
      '#!/bin/sh\n# not a comment to YAML\nset -eu\n\naws s3api head-bucket --bucket "$STORAGE_BUCKET" || aws s3api create-bucket --bucket "$STORAGE_BUCKET"\n'],
    ['strip-chomped block scalar', cm.data.enabled_plugins, '[rabbitmq_management,rabbitmq_prometheus].'],
    ['wrapped plain scalar', cm.metadata.annotations.note, 'a long note that kustomize wraps onto a second line when it passes the line width'],
    ['quoted key and quoted number stay strings', parsed.find((o) => o.metadata?.name === 'api').spec.template.spec.containers[0].env[1], { name: 'PORT', value: '3000' }],
    ['block scalar in a sequence', parsed.find((o) => o.metadata?.name === 'worker' && o.kind === 'Deployment').spec.template.spec.initContainers[0].command,
      ['sh', '-c', 'until aws s3api head-bucket --bucket fiapx; do sleep 2; done']],
    ['double-quoted escapes and folding', parseYamlStream('a: "x\\ty # z\n  \\u00e9nd"\nb: \'it\'\'s\'\n')[0], { a: 'x\ty # z énd', b: "it's" }],
  ];
  for (const [name, got, expected] of parserCases) {
    if (!same(got, expected)) failures.push(`parser: ${name}: got ${JSON.stringify(got)}, expected ${JSON.stringify(expected)}`);
  }

  // K8S-04: the static scan. The planted sources build the tool name at run
  // time, so this file itself holds no raw kubectl string.
  const tool = ['kube', 'ctl'].join('');
  const scanCases = [
    ['spawnSync of the bare binary', { 'k8s-up.mjs': `import { spawnSync } from 'node:child_process';\nspawnSync('${tool}', ['apply', '-f', '-']);\n` },
      ['scripts/k8s-up.mjs:2: spawns kubectl directly; call kubectl() from scripts/kube.mjs, which pins --context kind-fiapx']],
    ['execSync of a command line', { 'smoke.mjs': `// header\nexecSync("${tool} get pods -n fiapx");\n` },
      ['scripts/smoke.mjs:2: spawns kubectl directly; call kubectl() from scripts/kube.mjs, which pins --context kind-fiapx']],
    ['a shell string without the context', { 'down.mjs': `spawnSync('sh', ['-c', \`${tool} delete ns fiapx\`]);\n` },
      ['scripts/down.mjs:1: spawns kubectl directly; call kubectl() from scripts/kube.mjs, which pins --context kind-fiapx']],
    ['an absolute path to the binary', { 'x.mjs': `const bin = "/usr/local/bin/${tool}";\n` },
      ['scripts/x.mjs:1: spawns kubectl directly; call kubectl() from scripts/kube.mjs, which pins --context kind-fiapx']],
    ['a near-miss context in a command line', { 'y.mjs': `run('${tool} --context kind-fiapx2 get pods');\n` },
      ['scripts/y.mjs:1: spawns kubectl directly; call kubectl() from scripts/kube.mjs, which pins --context kind-fiapx']],
    ['kube.mjs itself may spawn it', { 'kube.mjs': `spawner('${tool}', args);\n` }, []],
    ['a printed hint with the pinned context', { 'k8s-up.mjs': `console.log('watch: ${tool} --context kind-fiapx -n fiapx get hpa -w');\n` }, []],
    ['a call through the helper', { 'k8s-up.mjs': `kubectl(['get', 'pods']);\n` }, []],
    ['a comment naming a command line', { 'check.mjs': `// renders with \`${tool} kustomize k8s\`\nconst x = 1;\n` }, []],
    ['a spawn after a comment on the same line is still found', { 'z.mjs': `const a = 1; // note\nspawnSync('${tool}', []); // raw\n` },
      ['scripts/z.mjs:2: spawns kubectl directly; call kubectl() from scripts/kube.mjs, which pins --context kind-fiapx']],
  ];
  for (const [name, files, expected] of scanCases) {
    const got = rawKubectlProblems(files);
    if (!same(got, expected)) failures.push(`scan: ${name}: got ${JSON.stringify(got)}, expected ${JSON.stringify(expected)}`);
    else if (expected.length > 0) rejected += 1;
    else accepted += 1;
  }
  // The committed scripts pass the scan.
  const committed = rawKubectlProblems(scriptSources(dirname(SELF)));
  if (committed.length > 0) failures.push(`scan: the committed scripts: ${JSON.stringify(committed)}`);

  // The script itself, on a render whose worker sets replicas, must exit
  // non-zero with the message on stderr; on the complete render it exits 0;
  // on a render that lost the catalog manifest it exits non-zero naming it.
  const scratch = mkdtempSync(join(tmpdir(), 'check-kubernetes-'));
  try {
    const bad = completeDocs();
    corrupt('Deployment/worker', 'spec:\n  selector:', 'spec:\n  replicas: 1\n  selector:')(bad);
    writeFileSync(join(scratch, 'bad.yaml'), joinDocs(bad));
    writeFileSync(join(scratch, 'good.yaml'), joinDocs(completeDocs()));
    const lost = completeDocs();
    delete lost['Deployment/catalog'];
    writeFileSync(join(scratch, 'lost.yaml'), joinDocs(lost));
    const spawn = (file) => spawnSync(process.execPath, [SELF], { encoding: 'utf8', env: { ...process.env, K8S_RENDER: join(scratch, file) } });
    const spawnedBad = spawn('bad.yaml');
    const expected = 'check-kubernetes: Deployment/worker: must not set spec.replicas; the KEDA HPA owns the replica count\n';
    if (spawnedBad.status === 0) failures.push('spawned run on a render whose worker sets replicas exited 0, expected non-zero');
    if (spawnedBad.stderr !== expected) failures.push(`spawned run printed ${JSON.stringify(spawnedBad.stderr)}, expected ${JSON.stringify(expected)}`);
    const spawnedGood = spawn('good.yaml');
    if (spawnedGood.status !== 0) failures.push(`spawned run on the good render exited ${spawnedGood.status}: ${JSON.stringify(spawnedGood.stderr)}`);
    const spawnedLost = spawn('lost.yaml');
    const expectedLost = `check-kubernetes: ${missing('Deployment/catalog')}\n`;
    if (spawnedLost.status === 0) failures.push('spawned run on a render without the catalog Deployment exited 0, expected non-zero');
    if (spawnedLost.stderr !== expectedLost) failures.push(`spawned run without catalog printed ${JSON.stringify(spawnedLost.stderr)}, expected ${JSON.stringify(expectedLost)}`);
  } finally {
    rmSync(scratch, { recursive: true, force: true });
  }

  if (failures.length > 0) {
    for (const failure of failures) console.error(`check-kubernetes self-test failed: ${failure}`);
    process.exit(1);
  }
  console.log(
    `check-kubernetes self-test passed: ${rejected} corruptions rejected with the exact message, ${accepted} good inputs accepted, ${parserCases.length} parser readings exact, the committed scripts pass the scan, spawned failures (worker replicas, catalog missing) exited non-zero and spawned complete render exited 0`,
  );
}

// Only when run as a script: the up command and the smoke may import the
// parser and the rules.
if (process.argv[1] === SELF) {
  if (process.argv.includes('--self-test')) {
    selfTest();
  } else {
    main();
  }
}
